import {escapeHTML as e} from '../../shared/primitives.js';
import {icon} from '../../shared/ui.js';
import {regionMembers,regionLabel} from './domain.js';
export function atlasSettings(c) {
 return `<section class="panel"><div class="section-line"><h2>Mapas deste mundo</h2><button data-action="new-map">${icon('plus')} Mapa</button></div>${c.maps.map(m=>`<div class="map-list-item"><img src="${e(m.image)}" alt="${e(m.name)}" loading="lazy"><div><strong>${e(m.name)}</strong><small>${c.locations.filter(l=>l.mapId===m.id).length} localidades</small></div><button class="text-button" data-edit-map="${e(m.id)}">Editar</button></div>`).join('')||'<p>Adicione a primeira imagem de mapa.</p>'}</section><section class="panel"><div class="section-line"><h2>Localidades</h2><button data-action="new-location">${icon('plus')} Local</button></div><div class="location-list">${c.locations.map(l=>`<button data-edit-location="${e(l.id)}"><span>${icon('pin')} ${e(l.name)}</span><small>${l.x.toFixed(1)}%, ${l.y.toFixed(1)}%</small></button>`).join('')}</div></section><section class="panel regions-settings"><div class="section-line"><h2>Regiões e sub-regiões</h2><button data-action="new-region">${icon('plus')} Região / local</button></div><p class="muted">Conecte os mapas em níveis. Os locais ilustrados aparecem dentro da sua região.</p>${c.regions.map(r=>`<div class="region-setting-row"><button class="text-button" data-region-map="${e(r.mapId)}">${icon('map')} ${e(regionLabel(c,r.id))}</button><span>${regionMembers(c,r.id).length} personagens</span><button data-edit-region="${e(r.id)}">Editar</button></div>`).join('')||'<p>Adicione um mapa e conecte a primeira região.</p>'}</section>`;
}
